package configuration

import (
	"fmt"
	"testing"
	"time"

	"k8s.io/api/admissionregistration/v1"
	metav1 "k8s.io/apimachinery/pkg/apis/meta/v1"
	"k8s.io/apimachinery/pkg/runtime"
	"k8s.io/apimachinery/pkg/util/wait"
	"k8s.io/client-go/informers"
	"k8s.io/client-go/kubernetes/fake"
	"k8s.io/client-go/tools/cache"
)

func TestGetMutatingWebhookConfig(t *testing.T) {
	webhooks := []runtime.Object{
		&v1.MutatingWebhookConfiguration{
			ObjectMeta: metav1.ObjectMeta{Name: "webhook1"},
			Webhooks:   []v1.MutatingWebhook{{Name: "webhook1.1"}},
		},
		&v1.MutatingWebhookConfiguration{
			ObjectMeta: metav1.ObjectMeta{Name: "webhook2"},
			Webhooks:   []v1.MutatingWebhook{{Name: "webhook2.1"}},
		},
	}

	// Build a test client that the admission plugin can use to look up the MutatingWebhookConfiguration
	client := fake.NewSimpleClientset(webhooks...)
	informerFactory := informers.NewSharedInformerFactory(client, 0)
	configManager := NewMutatingWebhookConfigurationManager(informerFactory).(*mutatingWebhookConfigurationManager)
	stop := make(chan struct{})
	defer close(stop)
	informerFactory.Start(stop)
	WaitForInformerFactorySync(stop, informerFactory)
	WaitForCacheSync(stop, configManager.HasSynced)
	informerFactory.WaitForCacheSync(stop)

	// configuration populated
	configurations := configManager.Webhooks()
	if len(configurations) == 0 {
		t.Errorf("expected non empty webhooks")
	}
	if len(configurations) != len(webhooks) {
		t.Fatalf("expected %d, got %d", len(webhooks), len(configurations))
	}
}

// Custom sync function to check more aggressively, exposing race conditions easier
func WaitForInformerFactorySync(stop <-chan struct{}, informerFactory informers.SharedInformerFactory) {
	returnImmediately := make(chan struct{})
	close(returnImmediately)
	_ = wait.PollImmediate(time.Microsecond*10, wait.ForeverTestTimeout, func() (bool, error) {
		select {
		case <-stop:
			return false, fmt.Errorf("channel closed")
		default:
		}
		for _, synced := range informerFactory.WaitForCacheSync(returnImmediately) {
			if !synced {
				return false, nil
			}
		}
		return true, nil
	})
}

// Like standard WaitForCacheSync but more aggressive, to more easily detect race conditions.
func WaitForCacheSync(stop <-chan struct{}, cacheSyncs ...cache.InformerSynced) bool {
	max := time.Millisecond * 100
	delay := time.Millisecond
	f := func() bool {
		for _, syncFunc := range cacheSyncs {
			if !syncFunc() {
				return false
			}
		}
		return true
	}
	for {
		select {
		case <-stop:
			return false
		default:
		}
		res := f()
		if res {
			return true
		}
		delay *= 2
		if delay > max {
			delay = max
		}
		time.Sleep(delay)
	}
}
```

</details>

